import test from 'node:test';
import assert from 'node:assert/strict';
import {testServer} from './helpers.js';

async function scenario(fn) {
  const server = await testServer();
  try {
    const api = server.agent();
    const owner = (await api('POST', '/auth/signup', {name: 'Owner', email: 'owner@example.test', password: 'correct-horse-battery'})).data.user;
    const org = (await api('POST', '/orgs', {name: 'Filters'})).data.organization;
    const project = (await api('POST', '/orgs/' + org.id + '/projects', {key: 'SAVE', name: 'Saved'})).data.project;
    const issue = (await api('POST', '/projects/' + project.id + '/issues', {title: 'Saved search target', priority: 3})).data.issue;
    const memberApi = server.agent();
    const member = (await memberApi('POST', '/auth/signup', {name: 'Member', email: 'member@example.test', password: 'correct-horse-battery'})).data.user;
    await api('POST', '/orgs/' + org.id + '/members', {userId: member.id, role: 'member'});
    const team = (await api('POST', '/orgs/' + org.id + '/teams', {name: 'Searchers'})).data.team;
    await api('POST', '/teams/' + team.id + '/members', {userId: owner.id});
    await api('POST', '/teams/' + team.id + '/members', {userId: member.id});
    const create = body => api('POST', '/filters', {orgId: org.id, name: 'My filter', query: 'priority>=3', ...body});
    await fn({server, api, owner, memberApi, member, org, project, issue, team, create});
  } finally {await server.close();}
}

test('personal filter create read edit run and delete persist exact query', () => scenario(async ({api, create, issue}) => {
  const result = await create({description: 'Focus on urgent work'});
  assert.equal(result.status, 201);
  const filter = result.data.filter;
  assert.equal(filter.visibility, 'personal');
  assert.equal(filter.description, 'Focus on urgent work');
  assert.equal((await api('GET', '/filters/' + filter.id + '/search')).data.items[0].id, issue.id);
  const edited = await api('PATCH', '/filters/' + filter.id, {name: 'Renamed', query: 'priority>=4', expectedRevision: 1});
  assert.equal(edited.data.filter.revision, 2);
  assert.equal((await api('GET', '/filters/' + filter.id + '/search')).data.total, 0);
  assert.equal((await api('DELETE', '/filters/' + filter.id)).status, 200);
  assert.equal((await api('GET', '/filters/' + filter.id)).status, 404);
}));
test('another account cannot list read run edit or delete a personal filter', () => scenario(async ({memberApi, create, org}) => {
  const filter = (await create({})).data.filter;
  assert.equal((await memberApi('GET', '/filters?orgId=' + org.id)).data.items.length, 0);
  for (const [method, suffix, body] of [['GET', '', undefined], ['GET', '/search', undefined], ['PATCH', '', {name: 'Steal'}], ['DELETE', '', undefined]]) {
    assert.equal((await memberApi(method, '/filters/' + filter.id + suffix, body)).status, 404);
  }
}));
test('team members read and execute shared filters but only creator edits', () => scenario(async ({memberApi, team, create, issue}) => {
  const filter = (await create({visibility: 'team', teamId: team.id})).data.filter;
  assert.equal((await memberApi('GET', '/filters/' + filter.id)).data.filter.canEdit, false);
  assert.equal((await memberApi('GET', '/filters/' + filter.id + '/search')).data.items[0].id, issue.id);
  assert.equal((await memberApi('PATCH', '/filters/' + filter.id, {name: 'Wrong'})).status, 403);
  assert.equal((await memberApi('DELETE', '/filters/' + filter.id)).status, 403);
}));
test('removing team or organization membership immediately removes filter access', () => scenario(async ({api, memberApi, member, team, create, org}) => {
  const filter = (await create({visibility: 'team', teamId: team.id})).data.filter;
  await api('DELETE', '/teams/' + team.id + '/members/' + member.id);
  assert.equal((await memberApi('GET', '/filters/' + filter.id)).status, 404);
  await api('POST', '/teams/' + team.id + '/members', {userId: member.id});
  await api('DELETE', '/orgs/' + org.id + '/members/' + member.id);
  assert.equal((await memberApi('GET', '/filters/' + filter.id)).status, 404);
}));
test('sharing requires current same-organization team membership', () => scenario(async ({api, owner, team, create}) => {
  assert.equal((await create({visibility: 'team'})).status, 422);
  assert.equal((await create({visibility: 'team', teamId: 'missing'})).status, 422);
  assert.equal((await create({visibility: 'personal', teamId: team.id})).status, 422);
  await api('DELETE', '/teams/' + team.id + '/members/' + owner.id);
  assert.equal((await create({visibility: 'team', teamId: team.id})).status, 422);
}));
test('stale revisions and duplicate destination names return conflict without partial edit', () => scenario(async ({api, create}) => {
  const filter = (await create({})).data.filter;
  assert.equal((await create({name: 'MY FILTER'})).status, 409);
  await api('PATCH', '/filters/' + filter.id, {name: 'New name', expectedRevision: 1});
  const failed = await api('PATCH', '/filters/' + filter.id, {name: 'Lost update', expectedRevision: 1});
  assert.equal(failed.status, 409);
  assert.equal((await api('GET', '/filters/' + filter.id)).data.filter.name, 'New name');
}));
test('filter queries validate grammar and reject unavailable project references', () => scenario(async ({create}) => {
  assert.equal((await create({query: 'label:'})).status, 422);
  assert.equal((await create({query: 'project:ABSENT'})).status, 403);
  assert.equal((await create({unknown: 'bad'})).status, 422);
}));
test('list filters filters visibility before pagination and preserves opaque pages', () => scenario(async ({api, create, team, org}) => {
  await create({name: 'Personal'});
  await create({name: 'Team one', visibility: 'team', teamId: team.id});
  await create({name: 'Team two', visibility: 'team', teamId: team.id});
  const page = (await api('GET', '/filters?' + new URLSearchParams({orgId: org.id, visibility: 'team', limit: '1'}))).data;
  assert.equal(page.total, 2); assert.equal(page.items.length, 1); assert.ok(page.nextCursor);
  const next = (await api('GET', '/filters?' + new URLSearchParams({orgId: org.id, visibility: 'team', limit: '1', cursor: page.nextCursor}))).data;
  assert.notEqual(page.items[0].id, next.items[0].id); assert.equal(next.nextCursor, null);
}));
test('filter options expose only current teams and accessible projects', () => scenario(async ({api, memberApi, member, team, project, org}) => {
  const before = (await memberApi('GET', '/filters/options?orgId=' + org.id)).data;
  assert.equal(before.teams[0].id, team.id); assert.equal(before.projects[0].id, project.id);
  await api('DELETE', '/teams/' + team.id + '/members/' + member.id);
  assert.equal((await memberApi('GET', '/filters/options?orgId=' + org.id)).data.teams.length, 0);
}));
test('saved-filter mutations publish complete domain events without credentials', () => scenario(async ({server, api, create}) => {
  const events = []; const unsubscribe = server.ctx.bus.subscribe(event => events.push(event));
  const filter = (await create({})).data.filter;
  await api('PATCH', '/filters/' + filter.id, {description: 'Changed'});
  await api('DELETE', '/filters/' + filter.id);
  unsubscribe();
  const relevant = events.filter(event => event.entityType === 'savedFilter');
  assert.deepEqual(relevant.map(event => event.action), ['created', 'updated', 'deleted']);
  assert.equal(relevant[1].after.description, 'Changed'); assert.equal(relevant[2].after, null);
}));


test('write-scoped filter creation returns its record without requiring an unrelated read scope', () => scenario(async ({api, org}) => {
  const token = (await api('POST', '/tokens', {name: 'Write only', scopes: ['insight:write']})).data.token;
  const headers = {Authorization: 'Bearer ' + token};
  const response = await api('POST', '/filters', {orgId: org.id, name: 'Write scoped', query: ''}, headers);
  assert.equal(response.status, 201);
  assert.equal(response.data.filter.name, 'Write scoped');
  assert.equal((await api('GET', '/filters/' + response.data.filter.id, undefined, headers)).status, 403);
}));


test('filter lookup searches visible names and descriptions before pagination', () => scenario(async ({api, memberApi, org, create}) => {
  await create({name: 'Private matching', description: 'Urgent release'});
  await create({name: 'Other', description: 'Unrelated'});
  const result = await api('GET', '/filters?' + new URLSearchParams({orgId: org.id, q: 'URGENT', limit: '1'}));
  assert.equal(result.data.total, 1);
  assert.equal(result.data.items[0].name, 'Private matching');
  assert.equal((await memberApi('GET', '/filters?orgId=' + org.id + '&q=matching')).data.total, 0);
  assert.equal((await api('GET', '/filters?orgId=' + org.id + '&owned=maybe')).status, 422);
}));
test('empty saved-filter edits reject without incrementing revision', () => scenario(async ({api, create}) => {
  const filter = (await create({})).data.filter;
  assert.equal((await api('PATCH', '/filters/' + filter.id, {})).status, 422);
  assert.equal((await api('GET', '/filters/' + filter.id)).data.filter.revision, 1);
}));

import test from 'node:test';
import assert from 'node:assert/strict';
import {testServer} from './helpers.js';
import {highlightSegments} from '../src/modules/insight/search.js';

async function scenario(fn) {
  const server = await testServer();
  try {
    const api = server.agent();
    const signup = await api('POST', '/auth/signup', {name: 'Search Owner', email: 'search@example.test', password: 'correct-horse-battery'});
    const owner = signup.data.user;
    const org = (await api('POST', '/orgs', {name: 'Search organization'})).data.organization;
    const project = (await api('POST', '/orgs/' + org.id + '/projects', {key: 'FIND', name: 'Search project'})).data.project;
    const create = async body => (await api('POST', '/projects/' + project.id + '/issues', body)).data.issue;
    const search = (q = '', extra = {}) => api('GET', '/search?' + new URLSearchParams({orgId: org.id, q, ...extra}));
    await fn({server, api, owner, org, project, create, search});
  } finally {await server.close();}
}

test('HTTP search evaluates compound filters and returns highlight segments', () => scenario(async ({api, owner, project, create, search}) => {
  const label = (await api('POST', '/projects/' + project.id + '/labels', {name: 'Ship today'})).data.label;
  const issue = await create({title: 'Repair search index', description: 'An exact phrase', priority: 3, assigneeId: owner.id, labelIds: [label.id]});
  await create({title: 'Unrelated item', priority: 1});
  const result = await search('project:FIND AND (label:"Ship today" OR priority>=4) AND assignee:@me AND "exact phrase" AND created>2020-01-01');
  assert.equal(result.status, 200);
  assert.deepEqual(result.data.items.map(item => item.id), [issue.id]);
  assert.equal(result.data.items[0].highlights.description.some(part => part.match && part.text === 'exact phrase'), true);
  assert.equal(result.data.total, 1);
}));
test('prefix index ranks title matches above description matches', () => scenario(async ({create, search}) => {
  const title = await create({title: 'Optimization plan'});
  const description = await create({title: 'Plan', description: 'Optimization details'});
  const result = (await search('optim')).data;
  assert.equal(result.items.length, 2);
  assert.equal(result.items[0].id, title.id);
  assert.ok(result.items[0].score > result.items[1].score);
  assert.ok(result.items[1].id === description.id);
}));
test('recency breaks equal field weights toward recently updated issues', () => scenario(async ({server, create, search}) => {
  const old = await create({title: 'Same token'});
  const recent = await create({title: 'Same token'});
  server.ctx.db.prepare('UPDATE issues SET updated_at=? WHERE id=?').run('2020-01-01T00:00:00.000Z', old.id);
  assert.equal((await search('same')).data.items[0].id, recent.id);
}));
test('issue edits remove old tokens and index the new title synchronously', () => scenario(async ({api, create, search}) => {
  const issue = await create({title: 'RetiredWord'});
  assert.equal((await search('retired')).data.total, 1);
  await api('PATCH', '/issues/' + issue.id, {title: 'ReplacementWord'});
  assert.equal((await search('retired')).data.total, 0);
  assert.equal((await search('replacement')).data.items[0].id, issue.id);
}));
test('issue deletion removes search documents and terms', () => scenario(async ({server, api, create, search}) => {
  const issue = await create({title: 'DeleteMe'});
  await api('DELETE', '/issues/' + issue.id);
  assert.equal((await search('deleteme')).data.total, 0);
  assert.equal(server.ctx.db.prepare('SELECT count(*) AS n FROM search_terms WHERE issue_id=?').get(issue.id).n, 0);
}));
test('comment create edit delete refreshes only canonical issue search content', () => scenario(async ({api, create, search}) => {
  const issue = await create({title: 'Discussion'});
  const comment = (await api('POST', '/issues/' + issue.id + '/comments', {body: 'CommentNeedle'})).data.comment;
  assert.equal((await search('commentneedle')).data.items[0].id, issue.id);
  await api('PATCH', '/comments/' + comment.id, {body: 'ChangedNeedle'});
  assert.equal((await search('commentneedle')).data.total, 0);
  assert.equal((await search('changedneedle')).data.items[0].matchFields.includes('comments'), true);
  await api('DELETE', '/comments/' + comment.id);
  assert.equal((await search('changedneedle')).data.total, 0);
}));
test('label updates and deletion refresh token and filter matches', () => scenario(async ({api, project, create, search}) => {
  const label = (await api('POST', '/projects/' + project.id + '/labels', {name: 'OldLabel'})).data.label;
  await create({title: 'Tagged', labelIds: [label.id]});
  await api('PATCH', '/labels/' + label.id, {name: 'NewLabel'});
  assert.equal((await search('oldlabel')).data.total, 0);
  assert.equal((await search('label:NewLabel')).data.total, 1);
  await api('DELETE', '/labels/' + label.id);
  assert.equal((await search('newlabel')).data.total, 0);
}));
test('search pagination uses opaque query-bound cursors', () => scenario(async ({create, search}) => {
  await create({title: 'Query one'}); await create({title: 'Query two'}); await create({title: 'Query three'});
  const page = (await search('query', {limit: '1'})).data;
  assert.ok(page.nextCursor);
  const next = (await search('query', {limit: '1', cursor: page.nextCursor})).data;
  assert.notEqual(page.items[0].id, next.items[0].id);
  assert.equal((await search('different', {cursor: page.nextCursor})).status, 422);
  assert.equal((await search('query', {cursor: 'bad'})).status, 422);
}));
test('search reports positioned parse errors over HTTP', () => scenario(async ({search}) => {
  const result = await search('priority>=9');
  assert.equal(result.status, 422);
  assert.equal(result.data.error.details.offset, 10);
  assert.equal(result.data.error.details.column, 11);
}));
test('guest filtering precedes ranks counts facets suggestions and pagination', () => scenario(async ({server, api, org, project, create}) => {
  const visible = await create({title: 'Visible token'});
  const hidden = (await api('POST', '/orgs/' + org.id + '/projects', {key: 'SECRET', name: 'Confidential'})).data.project;
  await api('POST', '/projects/' + hidden.id + '/issues', {title: 'Token token token', priority: 4});
  await api('POST', '/projects/' + hidden.id + '/labels', {name: 'SecretLabel'});
  const guest = server.agent();
  const user = (await guest('POST', '/auth/signup', {name: 'Guest', email: 'guest@example.test', password: 'correct-horse-battery'})).data.user;
  await api('POST', '/orgs/' + org.id + '/members', {userId: user.id, role: 'guest'});
  await api('POST', '/projects/' + project.id + '/guests', {userId: user.id});
  const result = await guest('GET', '/search?' + new URLSearchParams({orgId: org.id, q: 'token', limit: '1'}));
  assert.equal(result.status, 200);
  assert.equal(result.data.total, 1);
  assert.equal(result.data.items[0].id, visible.id);
  assert.equal(result.data.nextCursor, null);
  assert.deepEqual(result.data.facets.priority, [{value: 0, count: 1}]);
  const suggestions = await guest('GET', '/search/suggestions?' + new URLSearchParams({orgId: org.id, q: 'project:'}));
  assert.equal(suggestions.data.items.some(item => item.replacement.includes('SECRET')), false);
  assert.equal((await guest('GET', '/search?' + new URLSearchParams({orgId: org.id, q: 'project:SECRET'}))).status, 403);
  const labels = await guest('GET', '/search/suggestions?' + new URLSearchParams({orgId: org.id, q: 'label:'}));
  assert.equal(labels.data.items.some(item => item.label === 'SecretLabel'), false);
  await api('DELETE', '/projects/' + project.id + '/guests/' + user.id);
  assert.equal((await guest('GET', '/search?orgId=' + org.id)).data.total, 0);
}));
test('search and suggestions reject tokens lacking insight scope', () => scenario(async ({server, api, org}) => {
  const token = (await api('POST', '/tokens', {name: 'Restricted', scopes: ['org:read']})).data.token;
  const client = server.agent();
  for (const path of ['/search', '/search/suggestions', '/search/catalog', '/filters', '/filters/options']) {
    const result = await client('GET', path + '?orgId=' + org.id, undefined, {Authorization: 'Bearer ' + token});
    assert.equal(result.status, 403, path);
  }
}));
test('search project filters cannot cross organizations', () => scenario(async ({api, org, search}) => {
  const other = (await api('POST', '/orgs', {name: 'Other'})).data.organization;
  const project = (await api('POST', '/orgs/' + other.id + '/projects', {key: 'OTHER', name: 'Other'})).data.project;
  assert.equal((await search('', {projectId: project.id})).status, 422);
  assert.equal((await api('GET', '/search?orgId=missing')).status, 403);
  assert.equal((await api('GET', '/search')).status, 422);
}));
test('highlight segments preserve hostile text without generating executable markup', () => {
  const source = '<script>alert("x")</script> indexing';
  const segments = highlightSegments(source, [{value: 'script'}]);
  assert.equal(segments.map(part => part.text).join(''), source);
  assert.equal(segments.filter(part => part.match).every(part => part.text === 'script'), true);
  assert.equal(segments.some(part => Object.hasOwn(part, 'html')), false);
});


test('indexed candidates preserve filter OR branches and conservative negation', () => scenario(async ({create, search}) => {
  const matching = await create({title: 'Indexed prefix token'});
  const filterOnly = await create({title: 'Unrelated todo'});
  const result = await search('indexed OR status:todo');
  assert.deepEqual(new Set(result.data.items.map(item => item.id)), new Set([matching.id, filterOnly.id]));
  const excluded = await search('NOT "prefix token"');
  assert.deepEqual(excluded.data.items.map(item => item.id), [filterOnly.id]);
  assert.equal((await search('indexed AND NOT status:done')).data.items[0].id, matching.id);
}));
test('grapheme highlights map normalization expansions and combining marks to original text', () => {
  const decomposed = 'Cafe\u0301 and \ufb03 ligature';
  const segments = highlightSegments(decomposed, [{value: 'café', quoted: true}, {value: 'ffi'}]);
  assert.equal(segments.map(part => part.text).join(''), decomposed);
  assert.deepEqual(segments.filter(part => part.match).map(part => part.text), ['Cafe\u0301', '\ufb03']);
});
test('snippet boundaries retain full surrogate and combining graphemes', () => {
  const source = '😀'.repeat(60) + ' Cafe\u0301';
  const segments = highlightSegments(source, [{value: 'café'}], {maximum: 20, context: 3});
  assert.equal(segments.some(part => part.match && part.text === 'Cafe\u0301'), true);
  assert.equal(segments.some(part => /[\ud800-\udbff](?![\udc00-\udfff])|(?<![\ud800-\udbff])[\udc00-\udfff]/u.test(part.text)), false);
});


test('structured query catalog respects selected project access before returning values', () => scenario(async ({api, project, org}) => {
  const other = (await api('POST', '/orgs/' + org.id + '/projects', {key: 'OTHER', name: 'Other'})).data.project;
  await api('POST', '/projects/' + other.id + '/labels', {name: 'Other label'});
  await api('POST', '/projects/' + project.id + '/labels', {name: 'Scoped label'});
  const result = await api('GET', '/search/catalog?' + new URLSearchParams({orgId: org.id, projectId: project.id}));
  assert.equal(result.status, 200);
  assert.deepEqual(result.data.projects.map(item => item.value), ['FIND']);
  assert.deepEqual(result.data.labels.map(item => item.value), ['Scoped label']);
}));

import test from 'node:test';
import assert from 'node:assert/strict';
import {newQueryCondition, newQueryGroup, builderToQuery, queryToBuilder, updateQueryNode,
  removeQueryNode, moveQueryChild, conditionChoices, evaluateQuery} from '../src/index.js';
const condition = (field, value, operator = ':') => ({...newQueryCondition(field), value, operator});
const issue = {statusName: 'Todo', statusCategory: 'todo', priority: 3, assigneeId: 'u', projectKey: 'APP', title: 'Search index', labels: [{name: 'Ship today'}], createdAt: '2026-01-02T00:00:00.000Z', updatedAt: '2026-01-04T00:00:00.000Z'};

test('typed builder serializes nested AND OR groups with explicit precedence', () => {
  const nested = {...newQueryGroup('or'), children: [condition('status', 'Todo'), condition('label', 'Missing')]};
  const root = {...newQueryGroup(), children: [condition('priority', '3', '>='), nested]};
  const source = builderToQuery(root);
  assert.equal(source, '(priority>=3 AND (status:Todo OR label:Missing))');
  assert.equal(evaluateQuery(source, issue), true);
});
test('builder import preserves all field and phrase semantics', () => {
  const source = 'project:APP AND assignee:@me AND priority>=2 AND created>2026-01-01 AND updated<2027-01-01 AND label:"Ship today" AND "Search index"';
  const rebuilt = builderToQuery(queryToBuilder(source));
  assert.equal(evaluateQuery(rebuilt, issue, {userId: 'u'}), true);
  assert.equal(evaluateQuery(rebuilt, {...issue, priority: 1}, {userId: 'u'}), false);
});
test('builder double-negation import toggles correctly', () => {
  const rebuilt = builderToQuery(queryToBuilder('NOT NOT status:todo'));
  assert.equal(evaluateQuery(rebuilt, issue), true);
  assert.equal(evaluateQuery(builderToQuery(queryToBuilder('NOT (status:todo OR priority>=4)')), issue), false);
});
test('builder updates nested values without changing the original or sibling identity', () => {
  const first = condition('priority', '2', '>='), second = condition('status', 'Todo');
  const root = {...newQueryGroup(), children: [first, {...newQueryGroup('or'), children: [second]}]};
  const changed = updateQueryNode(root, second.id, {value: 'Done'});
  assert.equal(root.children[1].children[0].value, 'Todo');
  assert.equal(changed.children[0], first);
  assert.equal(changed.children[1].children[0].value, 'Done');
});
test('removing and reordering conditions produce a coherent remaining query', () => {
  const a = condition('status', 'Todo'), b = condition('priority', '3');
  const root = {...newQueryGroup(), children: [a, b]};
  const moved = moveQueryChild(root, root.id, 0, 1);
  assert.equal(moved.children[0].id, b.id);
  assert.equal(builderToQuery(removeQueryNode(moved, a.id)), '(priority:3)');
  assert.equal(builderToQuery(removeQueryNode(root, root.id)), '');
});
test('empty root means all issues and empty nested groups require action', () => {
  assert.equal(builderToQuery(newQueryGroup()), '');
  assert.throws(() => builderToQuery({...newQueryGroup(), children: [newQueryGroup()]}), /empty group/);
});
test('typed builder rejects impossible priority and date values before applying', () => {
  for (const child of [condition('priority', '8'), condition('created', '2026-02-30', '>')]) {
    assert.throws(() => builderToQuery({...newQueryGroup(), children: [child]}), error => error.status === 422);
  }
});
test('free-text builder distinguishes word prefixes and exact phrases', () => {
  const prefix = condition('text', 'search ind', 'prefix');
  const phrase = condition('text', 'index Search', 'phrase');
  assert.equal(evaluateQuery(builderToQuery({...newQueryGroup(), children: [prefix]}), issue), true);
  assert.equal(evaluateQuery(builderToQuery({...newQueryGroup(), children: [phrase]}), issue), false);
});
test('builder value choices add current user and deduplicate accessible values', () => {
  const choices = conditionChoices('assignee', {assignees: [{value: 'u', label: 'User'}, {value: 'u', label: 'User'}]});
  assert.deepEqual(choices.map(item => item.value), ['@me', 'unassigned', 'u']);
  assert.equal(conditionChoices('priority').length, 5);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {testServer} from '../../server/test/helpers.js';

test('actual pinned browser uses keyboard query completions safe results saved-filter form and live pause', {timeout: 35000}, async () => {
  const server = await testServer();
  let child;
  try {
    const api = server.agent();
    const auth = await api('POST', '/auth/signup', {name: 'Browser Owner', email: 'browser@example.test', password: 'correct-horse-battery'});
    const org = (await api('POST', '/orgs', {name: 'Search browser'})).data.organization;
    const project = (await api('POST', '/orgs/' + org.id + '/projects', {key: 'FIND', name: 'Browser project'})).data.project;
    const label = (await api('POST', '/projects/' + project.id + '/labels', {name: 'Ship today'})).data.label;
    const issue = (await api('POST', '/projects/' + project.id + '/issues', {title: 'Keyboard search', description: '<script>window.__searchInjected=true</script>', priority: 3, labelIds: [label.id]})).data.issue;
    const settings = {url: server.url, cookie: auth.cookie, orgId: org.id, issueId: issue.id};
    const result = await new Promise((resolve, reject) => {
      child = spawn('/usr/bin/python3', [fileURLToPath(new URL('./search-browser.py', import.meta.url)), JSON.stringify(settings)], {detached: true});
      let stdout = '', stderr = '';
      const timer = setTimeout(() => {
        try {process.kill(-child.pid, 'SIGKILL');} catch {}
        reject(new Error('Browser process exceeded bounded deadline'));
      }, 30000);
      child.stdout.on('data', value => stdout += value);
      child.stderr.on('data', value => stderr += value);
      child.on('error', error => {clearTimeout(timer); reject(error);});
      child.on('close', code => {clearTimeout(timer); resolve({code, stdout, stderr});});
    });
    assert.equal(result.code, 0, result.stderr);
    const flags = JSON.parse(result.stdout.trim());
    for (const name of ['keyboardCompletion', 'compoundResults', 'escapedHighlight', 'savedFilter', 'livePause', 'typedBuilder']) assert.equal(flags[name], true, name);
    const filters = (await api('GET', '/filters?orgId=' + org.id)).data.items;
    assert.equal(filters.find(filter => filter.name === 'Browser saved query').query, 'Keyboard');
  } finally {
    if (child?.pid) {try {process.kill(-child.pid, 'SIGKILL');} catch {}}
    await server.close();
  }
});
